const isPlatformOwner=user.role==='PLATFORM_OWNER';let sid=user.school_id||new URLSearchParams(location.search).get('school_id');if(isPlatformOwner&&!sid){location.href='/owner.html';return;}if(!sid){location.href='/owner.html';return;}const isAdmin=isPlatformOwner||['SCHOOL_ADMIN','ADMIN'].includes(user.role),isTeacher=true,isLeadership=['HEADTEACHER','DEPUTY_HEADTEACHER','SENIOR_TEACHER'].includes(user.role),isClassTeacher=user.role==='CLASS_TEACHER',isAnyTeacher=true;
const $=id=>document.getElementById(id), api=async(url,opt={})=>{const headers=Object.assign({'Authorization':'Bearer '+localStorage.getItem('token')},opt.headers||{});if(opt.body&&typeof opt.body!=='string'&&!(opt.body instanceof FormData)){headers['Content-Type']='application/json';opt.body=JSON.stringify(opt.body);}const r=await fetch(url,{...opt,headers});const raw=await r.text();let d={};if(raw.trim()){try{d=JSON.parse(raw)}catch{throw new Error(`Server returned an invalid response (HTTP ${r.status}).`)}}if(r.status===401){localStorage.removeItem('token');localStorage.removeItem('user');location.href='/login.html';throw new Error('Session expired. Please sign in again.')}if(!r.ok)throw new Error(d.error||`Request failed (${r.status})`);return d;};
