async function setupClassTeacherLearnerForm(){
    if(!isClassTeacher)return;
    try{
        const assignments=await api(`/api/people/${sid}/my-class-teacher-assignments`);state.classTeacherAssignments=assignments;
        const years=[...new Map(assignments.map(x=>[x.academic_year_id,{id:x.academic_year_id,year_label:x.year_label}])).values()];
        const classes=[...new Map(assignments.map(x=>[x.class_id,{id:x.class_id,name:x.class_name,stream:x.stream,year_id:x.academic_year_id,term_id:x.term_id}])).values()];
        opts($('ctLearnerYear'),years,x=>x.year_label,'Select academic year…');
        opts($('ctLearnerClass'),classes,x=>`${x.name} ${x.stream||''}`,'Select assigned class…');
        renderClassLists();
        renderLearnerFilters();
        renderLearners();
        if(years[0])$('ctLearnerYear').value=years[0].id;
        if(classes[0])$('ctLearnerClass').value=classes[0].id;
        $('classTeacherAddLearner').onclick=()=>{
            const box=$('classTeacherAddBox');
            box.style.display=box.style.display==='none'?'block':'none';
        };
        $('classTeacherLearnerForm').onsubmit=async e=>{
            e.preventDefault();
            const b=Object.fromEntries(new FormData(e.target));
            const cls=classes.find(x=>x.id===b.class_id);
            const yr=years.find(x=>x.id===b.academic_year_id);
            if(!cls||!yr){$('ctLearnerMsg').textContent='Select your assigned class and academic year.';return;}
            b.academic_year_id=cls.year_id||yr.id;
            const asn=assignments.find(x=>x.class_id===cls.id && x.academic_year_id===b.academic_year_id);
            b.term_id=asn?.term_id||'';
            try{
                await api(`/api/people/${sid}/learners`,{method:'POST',body:b});
                $('ctLearnerMsg').textContent='Learner added successfully.';
                e.target.reset();
                $('ctLearnerYear').value=b.academic_year_id;
                $('ctLearnerClass').value=cls.id;
                await load();
            }catch(x){$('ctLearnerMsg').textContent=x.message;}
        };
    }catch(x){
        console.warn('Class teacher learner workspace:',x.message);
    }
}
