async function loadLeadership(){try{const r=await api(`/api/people/${sid}/leadership`);$('leadershipList').innerHTML=r.map(x=>`<div class="item assignment-card"><span><b>${x.first_name||''} ${x.last_name||''}</b><br><span class="muted small">${x.staff_no||''} · ${x.login_email||x.email||''}</span></span><span class="pill">${x.role.replaceAll('_',' ')}</span></div>`).join('')||'<div class="notice">No leadership roles assigned yet.</div>';}catch(e){$('leadershipList').innerHTML='<div class="notice">Leadership information is available to authorized administrators.</div>';}}
