function safeOn(id,event,handler){const el=$(id);if(el)el.addEventListener(event,handler);return el;}
function setBusy(btn,busy,text){if(!btn)return;btn.disabled=busy;if(busy){btn.dataset.oldText=btn.textContent;btn.textContent=text||'Working…';}else if(btn.dataset.oldText){btn.textContent=btn.dataset.oldText;delete btn.dataset.oldText;}}
function showSection(id){const el=$(id);if(!el)return;const modules=['teacherMarking','identity','documents','billing','academic','classLists','people','userControl','assign','assess','markControl','results','merit','leadership','reports'];modules.forEach(mid=>{const x=$(mid);if(x){x.classList.add('portal-module');x.classList.toggle('pm-hidden',mid!==id);}});document.querySelectorAll('#navTabs button').forEach(b=>b.classList.toggle('active',b.dataset.target===id));el.scrollIntoView({behavior:'smooth',block:'start'});}
function wireNavigation(){const nav=$('navTabs');if(nav)nav.addEventListener('click',e=>{const b=e.target.closest('button[data-target]');if(!b)return;showSection(b.dataset.target);});}
function wireSignOut(){safeOn('signOut','click',()=>{localStorage.removeItem('token');localStorage.removeItem('user');location.replace('/login.html');});}
async function refreshAfterChange(message){if(message)alert(message);await load();}
async function loadResults(){
 const y=$('resYear')?.value,t=$('resTerm')?.value,c=$('resClass')?.value,su=$('resSubject')?.value,a=$('resAssessment')?.value;
 if(!y||!t)return alert('Select academic year and term first.');
 if(!c)return alert('Select a class first.');
 if(!isAdmin&&!isLeadership&&!su)return alert('Select your subject first.');
 const b=$('loadResults');setBusy(b,true,'Loading…');
 try{
   const qs=new URLSearchParams({academic_year_id:y,term_id:t,class_id:c});
   if(su)qs.set('subject_id',su); if(a)qs.set('assessment_id',a);
   const r=await api(`/api/assessments/${sid}/marks?${qs}`);
   $('resultRows').innerHTML=r.map(x=>`<tr><td>${esc([x.first_name,x.middle_name,x.last_name].filter(Boolean).join(' '))}</td><td>${esc(x.admission_no||'—')}</td><td>${esc(x.class_name||'')}</td><td>${esc(x.subject_name||'')}</td><td>${esc(x.assessment_name||'')}</td><td><b>${x.mark??'—'}</b></td><td>${x.max_mark??'—'}</td></tr>`).join('')||'<tr><td colspan="7">No saved marks found for this selection.</td></tr>';
 }catch(e){$('resultRows').innerHTML=`<tr><td colspan="7">${esc(e.message)}</td></tr>`;}finally{setBusy(b,false);}
}
function setupResultsControls(){
 const year=$('resYear'),term=$('resTerm'),cls=$('resClass'),sub=$('resSubject'),ass=$('resAssessment');
 if(!year||!term||!cls||!sub||!ass)return;
 const rebuildClasses=()=>{
   const y=String(year.value||'');
   let rows=[];
   if(isAdmin||isLeadership) rows=(state.classes||[]);
   else rows=[...(state.teacherAssignments||[])].filter(x=>!y||String(x.academic_year_id)===y).map(x=>({id:x.class_id,name:x.class_name,stream:x.stream,level_name:x.level_name}));
   rows=[...new Map(rows.map(x=>[String(x.id),x])).values()];
   opts(cls,rows,x=>`${x.name||x.class_name} ${x.stream||''} · ${x.level_name||''}`,'Select class…');
   sub.innerHTML='<option value="">Select subject…</option>';ass.innerHTML='<option value="">Select assessment…</option>';
 };
 const rebuildSubjects=async()=>{
   const y=String(year.value||''),c=String(cls.value||'');
   sub.innerHTML='<option value="">Select subject…</option>';ass.innerHTML='<option value="">Select assessment…</option>';
   if(!y||!c)return;
   let rows=[];
   if(isAdmin||isLeadership){
     rows=(state.assignments||[]).filter(x=>String(x.class_id)===c && String(x.academic_year_id)===y).map(x=>({id:x.subject_id,code:x.subject_code,name:x.subject_name}));
   }else{
     rows=(state.teacherAssignments||[]).filter(x=>String(x.class_id)===c && String(x.academic_year_id)===y).map(x=>({id:x.subject_id,code:x.subject_code,name:x.subject_name}));
   }
   rows=[...new Map(rows.map(x=>[String(x.id),x])).values()];
   opts(sub,rows,x=>`${x.name||x.code||'Subject'}`,'Select your subject…');
   if(rows.length===1){sub.value=rows[0].id;await rebuildAssessments();}
 };
 const rebuildAssessments=async()=>{
   const y=String(year.value||''),t=String(term.value||''),c=String(cls.value||''),s=String(sub.value||'');
   ass.innerHTML='<option value="">All assessments</option>';
   if(!y||!t||!c||!s)return;
   try{
     const all=await api(`/api/assessments/${sid}/${y}/${t}`);
     const rows=all.filter(x=>(!x.class_id||String(x.class_id)===c)&&(!x.subject_id||String(x.subject_id)===s));
     opts(ass,rows,x=>`${x.name}`,'All assessments');
     if(rows.length===1)ass.value=rows[0].id;
   }catch(e){console.warn('Saved-mark assessment filter:',e.message);}
 };
 year.addEventListener('change',async()=>{await terms(year.value,term);rebuildClasses();});
 term.addEventListener('change',rebuildAssessments);
 cls.addEventListener('change',rebuildSubjects);
 sub.addEventListener('change',rebuildAssessments);
 rebuildClasses();
}

