function initPromotion(){const fill=(id,arr,empty)=>opts($(id),arr,x=>`${x.name||x.class_name||x.year_label||''}${x.stream?' '+x.stream:''}`,empty);fill('promotionSourceYear',state.years,'Select source year…');fill('promotionDestinationYear',state.years,'Select destination year…');const sourceClasses=state.classes,destClasses=state.classes;fill('promotionSourceClass',sourceClasses,'Select source class…');fill('promotionDestinationClass',destClasses,'Select destination class…');safeOn('promotionSourceYear','change',async()=>{const y=$('promotionSourceYear').value;if(!y)return;try{const r=await api(`/api/people/${sid}/enrollments/${y}`);state.promotionEnrollments=r;$('promotionStatus').textContent=`${r.length} learner(s) found in source year.`;$('promotionLearners').innerHTML='';}catch(e){$('promotionStatus').textContent=e.message;}});safeOn('promotionSourceClass','change',()=>{if(state.promotionEnrollments){const c=$('promotionSourceClass').value;const r=state.promotionEnrollments.filter(x=>String(x.class_id)===String(c));$('promotionStatus').textContent=`${r.length} learner(s) found in the selected source class.`;}});safeOn('loadPromotionLearners','click',async()=>{const y=$('promotionSourceYear').value,c=$('promotionSourceClass').value;if(!y||!c)return alert('Select source academic year and source class first.');try{const r=await api(`/api/people/${sid}/enrollments/${y}`);state.promotionEnrollments=r.filter(x=>String(x.class_id)===String(c));$('promotionLearners').innerHTML=state.promotionEnrollments.map((x,i)=>`<label class="item"><input type="checkbox" class="promotion-learner" value="${x.learner_id}" checked> ${i+1}. ${esc([x.first_name,x.middle_name,x.last_name].filter(Boolean).join(' '))} · ${esc(x.admission_no||'')}</label>`).join('')||'<div class="notice">No learners found.</div>';}catch(e){alert(e.message);}});safeOn('promoteSelected','click',async()=>{const ids=[...document.querySelectorAll('.promotion-learner:checked')].map(x=>x.value);const sy=$('promotionSourceYear').value,sc=$('promotionSourceClass').value,dy=$('promotionDestinationYear').value,dc=$('promotionDestinationClass').value;if(!ids.length||!sy||!sc||!dy||!dc)return alert('Select source/destination and at least one learner.');try{const r=await api(`/api/people/${sid}/promote`,{method:'POST',body:{learner_ids:ids,source_year_id:sy,source_class_id:sc,destination_year_id:dy,destination_class_id:dc}});$('promotionStatus').textContent=`Successfully promoted ${r.promoted} learner(s).`;await load();}catch(e){alert(e.message);}});}
