async function setupTeacher(){
  const teacher=state.teachers.find(x=>String(x.user_id)===String(user.user_id||user.id));
  if(!teacher){$('teacherMsg').textContent='No teacher profile is linked to this login. Ask the School Administrator to link this login to the teacher profile.';return;}
  const a=await api(`/api/people/${sid}/teacher-assignments/${teacher.id}`); state.teacherAssignments=Array.isArray(a)?a:[];
  const yearSel=$('markYear'),termSel=$('markTerm'),assSel=$('markAssessment'),classSel=$('markClass'),subSel=$('markSubject'); if(!yearSel||!termSel||!assSel||!classSel||!subSel)return;
  const unique=(rows,key)=>[...new Map(rows.filter(x=>x&&x[key]).map(x=>[String(x[key]),x])).values()];
  const byYear=()=>state.teacherAssignments.filter(x=>String(x.academic_year_id)===String(yearSel.value));
  const byPeriod=()=>byYear().filter(x=>!termSel.value||!x.term_id||String(x.term_id)===String(termSel.value));
  const reset=()=>{state.bulkRoster=null;$('bulkMarkRows').innerHTML='<tr><td colspan="5">Choose an assessment, class and subject to load learners.</td></tr>';$('markContext').textContent='Choose an assessment to begin.';$('markDeadline').textContent='Not set';$('markSubmissionStatus').textContent='Ready to save';$('markProgress').textContent='0 / 0 entered';$('markProgressBar').style.width='0%';$('teacherMsg').textContent='Select an assessment to begin.';};
  opts(yearSel,unique(state.teacherAssignments,'academic_year_id'),x=>x.year_label,'Select academic year…'); opts(termSel,[],x=>x.name,'Select term…'); opts(assSel,[],x=>`${x.name} · ${x.assessment_type}`,'Select assessment…'); opts(classSel,[],x=>`${x.class_name||''} ${x.stream||''}`,'Select class…'); opts(subSel,[],x=>`${x.subject_code||''} · ${x.subject_name||''}`,'Select subject…');
  const loadRoster=async()=>{const y=yearSel.value,t=termSel.value,c=classSel.value,su=subSel.value,aid=assSel.value;if(!y||!t||!c||!su||!aid){reset();return;}const assignment=state.teacherAssignments.find(x=>String(x.academic_year_id)===String(y)&&(!x.term_id||String(x.term_id)===String(t))&&String(x.class_id)===String(c)&&String(x.subject_id)===String(su));if(!assignment){reset();$('teacherMsg').textContent='This subject/class is not assigned to you for the selected academic period.';return;}$('markAssignment').value=assignment.id;await loadBulkRoster(assignment);};
  const loadAssessments=async()=>{const y=yearSel.value,t=termSel.value,c=classSel.value,su=subSel.value;opts(assSel,[],x=>`${x.name} · ${x.assessment_type}`,'Select assessment…');reset();if(!y||!t||!c||!su)return;try{const all=await api(`/api/assessments/${sid}/${y}/${t}`);const rows=all.filter(x=>(!x.class_id||String(x.class_id)===String(c))&&(!x.subject_id||String(x.subject_id)===String(su)));opts(assSel,unique(rows,'id'),x=>`${x.name} · ${x.assessment_type}`,'Select assessment…');if(rows.length===1){assSel.value=rows[0].id;await loadRoster();}}catch(e){$('teacherMsg').textContent=e.message;}};
  const rebuildSubjects=async()=>{const rows=byPeriod().filter(x=>String(x.class_id)===String(classSel.value));const subjects=unique(rows,'subject_id');opts(subSel,subjects,x=>`${x.subject_code||''} · ${x.subject_name||''}`,'Select subject…');opts(assSel,[],x=>`${x.name} · ${x.assessment_type}`,'Select assessment…');reset();if(subjects.length===1){subSel.value=subjects[0].subject_id;await loadAssessments();}};
  const rebuildPeriod=async()=>{const rows=byPeriod(),classes=unique(rows,'class_id');opts(classSel,classes,x=>`${x.class_name||''} ${x.stream||''}`,'Select class…');opts(subSel,[],x=>`${x.subject_code||''} · ${x.subject_name||''}`,'Select subject…');opts(assSel,[],x=>`${x.name} · ${x.assessment_type}`,'Select assessment…');reset();if(classes.length===1){classSel.value=classes[0].class_id;await rebuildSubjects();}};
  const loadYear=async()=>{opts(termSel,[],x=>x.name,'Select term…');const y=yearSel.value;if(!y){reset();return;}const ts=await terms(y,termSel);if(ts[0])termSel.value=ts[0].id;await rebuildPeriod();};
  yearSel.onchange=loadYear;termSel.onchange=rebuildPeriod;classSel.onchange=rebuildSubjects;subSel.onchange=loadAssessments;assSel.onchange=loadRoster;
  if(yearSel.options[1]?.value){yearSel.value=yearSel.options[1].value;await loadYear();}
}
function currentMarkAssessment(){ const id=String($('markAssessment')?.value||''); return state.bulkRoster?.assessments?.find(a=>String(a.id)===id); }
function renderMarkDeadline(){ const a=currentMarkAssessment(),el=$('markDeadline'),inputs=document.querySelectorAll('.bulk-mark-input'); if(!a){if(el)el.textContent='Not set';return;} const expired=a.deadline_at&&new Date(a.deadline_at)<=new Date(); const closed=String(a.status||'OPEN').toUpperCase()!=='OPEN'; if(el)el.innerHTML=a.deadline_at?`${esc(new Date(a.deadline_at).toLocaleString())} · <span class="deadline-open">${expired?'DEADLINE PASSED':'OPEN'}</span>`:'No deadline set'; inputs.forEach(x=>x.disabled=false); const ss=$('markSubmissionStatus');if(ss)ss.textContent=a.submitted_at?'Submitted — corrections still allowed':'Not submitted'; const sb=$('submitMarks');if(sb)sb.disabled=false; const save=$('saveAllMarks');if(save)save.disabled=false; }
function renderBulkMarks(){ const r=state.bulkRoster;if(!r)return; const aid=String($('markAssessment').value||''); const rows=r.learners; const existing=new Map(); rows.forEach(l=>(Array.isArray(l.marks)?l.marks:[]).forEach(m=>{if(String(m.assessment_id)===aid)existing.set(String(l.learner_id),m);})); $('bulkMarkRows').innerHTML=rows.map((l,i)=>{const e=existing.get(String(l.learner_id)),v=e&&e.mark!=null?Number(e.mark).toString():'';return `<tr data-learner-id="${l.learner_id}"><td>${i+1}</td><td><div class="learner-cell">${l.passport_photo_url?`<img class="passport-mini" src="${l.passport_photo_url}" alt="">`:`<span class="avatar">${(l.first_name||'?')[0]}${(l.last_name||'?')[0]}</span>`}<b>${[l.first_name,l.middle_name,l.last_name].filter(Boolean).join(' ')}</b></div></td><td>${l.admission_no||'—'}</td><td><input class="bulk-mark-input" inputmode="decimal" type="number" step="0.01" min="0" max="${r.assessments.find(a=>String(a.id)===aid)?.max_mark||100}" value="${v}"></td><td class="save-status">${e?'Saved':'—'}</td></tr>`}).join('')||'<tr><td colspan="5">No learners are enrolled in this class for the selected academic year.</td></tr>'; updateMarkProgress(); renderMarkDeadline(); }
async function saveBulkMarks(onlyRow=null){const r=state.bulkRoster;if(!r)return;const aid=$('markAssessment').value;if(!aid)return alert('Select an assessment first.');const selected=onlyRow?[onlyRow]:[...document.querySelectorAll('#bulkMarkRows tr[data-learner-id]')];const rows=selected.map(tr=>({learner_id:tr.dataset.learnerId,mark:tr.querySelector('.bulk-mark-input')?.value??''}));try{const out=await api(`/api/assessments/${sid}/marks/save`,{method:'POST',body:{assignment_id:r.assignment.assignment_id,assessment_id:aid,rows}});selected.forEach(tr=>{const st=tr.querySelector('.save-status');if(st)st.textContent='Saved';});updateMarkProgress();$('teacherMsg').textContent=`Saved ${out.saved} mark${out.saved===1?'':'s'} successfully · ${r.assignment.subject_name} · ${r.assignment.class_name}.`;return true;}catch(e){$('teacherMsg').textContent=e.message;return false;}}
async function submitTeacherMarks(){const r=state.bulkRoster,a=currentMarkAssessment();if(!r||!a)return alert('Select an assignment and assessment first.');if(!confirm('Submit this assessment as complete? You can still auto-save corrections until the administrator deadline.'))return;await saveBulkMarks();try{const out=await api(`/api/assessments/${sid}/${r.assignment.academic_year_id}/${r.assignment.term_id}/${a.id}/submit`,{method:'POST',body:{}});$('teacherMsg').textContent=out.message;await loadBulkRoster((state.teacherAssignments||[]).find(x=>x.id===r.assignment.assignment_id));}catch(e){$('teacherMsg').textContent=e.message;}}

