safeOn('markAssessment','input',renderBulkMarks);$('saveAllMarks').addEventListener('click',()=>saveBulkMarks());$('submitMarks').addEventListener('click',submitTeacherMarks);$('markPdf').addEventListener('click',()=>{const a=$('markAssignment').value,ass=$('markAssessment').value;if(!a||!ass)return alert('Select subject/class and assessment first.');openProtectedPdf(`/api/assessments/${sid}/assignment/${a}/marks-pdf?assessment_id=${ass}`).catch(x=>alert(x.message));});$('bulkMarkRows').addEventListener('input',e=>{updateMarkProgress();if(e.target.classList.contains('bulk-mark-input')){e.target.closest('tr')?.querySelector('.save-status')&&(e.target.closest('tr').querySelector('.save-status').textContent='Saving…');clearTimeout(markSaveTimer);markSaveTimer=setTimeout(()=>saveBulkMarks(e.target.closest('tr')),900);}});$('bulkMarkRows').addEventListener('blur',e=>{if(e.target.classList.contains('bulk-mark-input'))saveBulkMarks(e.target.closest('tr'));},true);$('bulkMarkRows').addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.classList.contains('bulk-mark-input')){e.preventDefault();const tr=e.target.closest('tr[data-learner-id]');saveBulkMarks(tr).then(()=>{const next=tr?.nextElementSibling?.querySelector('.bulk-mark-input');if(next){next.focus();next.select();}});}});safeOn('myClassTeacherList','click',e=>{const b=e.target.closest('button[data-class-id]');if(!b)return;const year=b.dataset.yearId,term=b.dataset.termId,cls=b.dataset.classId;if(b.classList.contains('class-report-quick')){if(!term)return alert('This assignment has no term selected.');openProtectedPdf(`/api/reports/${sid}/class/${cls}/${year}/${term}/pdf`).catch(x=>alert(x.message));}else{if(!term)return alert('This assignment has no term selected.');openProtectedPdf(`/api/merit/${sid}/pdf?academic_year_id=${year}&term_id=${term}&class_id=${cls}`).catch(x=>alert(x.message));}});$('identityForm').addEventListener('submit',async e=>{e.preventDefault();try{await api(`/api/settings/${sid}/identity`,{method:'PUT',body:Object.fromEntries(new FormData(e.target))});alert('School identity saved.');}catch(x){alert(x.message)}});$('identityForm').primary_color.addEventListener('input',()=>applySchoolTheme({primary_color:$('identityForm').primary_color.value,secondary_color:$('identityForm').secondary_color.value}));$('identityForm').secondary_color.addEventListener('input',()=>applySchoolTheme({primary_color:$('identityForm').primary_color.value,secondary_color:$('identityForm').secondary_color.value}));$('logoForm').addEventListener('submit',async e=>{e.preventDefault();try{await api(`/api/settings/${sid}/logo`,{method:'POST',body:new FormData(e.target)});e.target.reset();await load();}catch(x){alert(x.message)}});
$('stampForm').addEventListener('submit',async e=>{e.preventDefault();try{await api(`/api/documents/${sid}/stamp`,{method:'POST',body:new FormData(e.target)});alert('School stamp uploaded and date-effective.');e.target.reset();}catch(x){alert(x.message)}});
$('announcementForm').addEventListener('submit',async e=>{e.preventDefault();try{await api(`/api/documents/${sid}/announcements`,{method:'POST',body:Object.fromEntries(new FormData(e.target))});alert('School announcement published.');e.target.reset();}catch(x){alert(x.message)}});
$('parentForm').addEventListener('submit',async e=>{e.preventDefault();try{await api(`/api/communications/${sid}/parents`,{method:'POST',body:Object.fromEntries(new FormData(e.target))});alert('Parent/guardian saved.');e.target.reset();loadParents();}catch(x){alert(x.message)}});
async function loadParents(){try{const p=await api(`/api/communications/${sid}/parents`);$('parentList').innerHTML=p.map(x=>`<div class="item"><b>${x.first_name} ${x.last_name}</b> · ${x.relationship||'Guardian'} · ${x.phone} · ${x.learner_count} learner(s)</div>`).join('')||'No parents added yet.';}catch{}}
