async function setupMarkControl(){try{opts($('mcYear'),state.years,x=>x.year_label);opts($('pubYear'),state.years,x=>x.year_label);opts($('anYear'),state.years,x=>x.year_label);opts($('pubLevel'),state.classes.reduce((a,c)=>a.some(x=>x.id===c.school_level_id)?a:a.concat([{id:c.school_level_id,name:c.level_name}]),[]),x=>x.name,'Select grade…');opts($('anLevel'),state.classes.reduce((a,c)=>a.some(x=>x.id===c.school_level_id)?a:a.concat([{id:c.school_level_id,name:c.level_name}]),[]),x=>x.name,'All grades');opts($('anClass'),state.classes,x=>`${x.name} ${x.stream||''}`,'All classes');if(state.years[0]){for(const id of ['mcTerm','pubTerm','anTerm'])await terms(state.years[0].id,$(id));await loadControlAssessments();await loadGradeRoster();}}catch(e){console.warn('Mark control centre:',e.message)}}
async function loadControlAssessments(){const y=$('mcYear').value;if(!y)return;await terms(y,$('mcTerm'));if(!$('mcTerm').value)return;const a=await api(`/api/assessments/${sid}/${y}/${$('mcTerm').value}`);opts($('mcAssessment'),a,x=>`${x.name} · ${x.assessment_type}`,'Select assessment…');const x=a[0];if(x){$('mcAssessment').value=x.id;$('mcDeadline').value=x.deadline_at?new Date(x.deadline_at).toISOString().slice(0,16):'';}}
async function loadGradeRoster(){const y=$('pubYear').value;if(!y||!$('pubLevel').value){$('gradePublishRoster').innerHTML='<div class="notice">Select a grade to load learners and parent phone numbers.</div>';return;}const rows=await api(`/api/communications/${sid}/grade-learners?academic_year_id=${encodeURIComponent(y)}&level_id=${encodeURIComponent($('pubLevel').value)}`);$('gradePublishRoster').innerHTML=`<table><thead><tr><th>Learner</th><th>Class</th><th>Parent / Guardian</th><th>Phone</th></tr></thead><tbody>${rows.map(x=>{const p=(x.parents||[]).filter(v=>v.phone);return `<tr><td><b>${esc([x.first_name,x.middle_name,x.last_name].filter(Boolean).join(' '))}</b><br><span class="muted small">${esc(x.admission_no||'')}</span></td><td>${esc(x.class_name)} ${esc(x.stream||'')}</td><td>${p.length?p.map(v=>esc(v.name)).join(', '):'<span class="muted">No SMS contact</span>'}</td><td class="grade-phone">${p.length?p.map(v=>esc(v.phone)).join('<br>'):'—'}</td></tr>`}).join('')||'<tr><td colspan="4">No active learners found for this grade.</td></tr>'}</tbody></table>`;}
async function runAnalytics(){const qs=new URLSearchParams({academic_year_id:$('anYear').value,term_id:$('anTerm').value});if($('anLevel').value)qs.set('level_id',$('anLevel').value);if($('anClass').value)qs.set('class_id',$('anClass').value);try{const r=await api(`/api/communications/${sid}/analytics?${qs}`);$('analyticsBox').innerHTML=`<div class="analytics-card"><b>Learners</b><div>${r.overall.learners}</div></div><div class="analytics-card"><b>Mark entries</b><div>${r.overall.mark_entries}</div></div><div class="analytics-card"><b>Mean</b><div>${r.overall.mean_mark??'—'}</div></div><div class="analytics-card"><b>Median</b><div>${r.overall.median_mark??'—'}</div></div><div class="analytics-card"><b>Lowest</b><div>${r.overall.min_mark??'—'}</div></div><div class="analytics-card"><b>Highest</b><div>${r.overall.max_mark??'—'}</div></div><div class="card-subsection"><h4>Subject performance</h4><div class="table-wrap"><table><thead><tr><th>Subject</th><th>Entries</th><th>Average</th><th>Min</th><th>Max</th></tr></thead><tbody>${r.subjects.map(x=>`<tr><td>${esc(x.name)}</td><td>${x.entries}</td><td><b>${x.average??'—'}</b></td><td>${x.min_mark??'—'}</td><td>${x.max_mark??'—'}</td></tr>`).join('')||'<tr><td colspan="5">No marks yet.</td></tr>'}</tbody></table></div></div><div class="card-subsection"><h4>Class comparison</h4><div class="table-wrap"><table><thead><tr><th>Class</th><th>Learners</th><th>Average</th></tr></thead><tbody>${r.classes.map(x=>`<tr><td>${esc(x.name)} ${esc(x.stream||'')}</td><td>${x.learners}</td><td><b>${x.average??'—'}</b></td></tr>`).join('')}</tbody></table></div></div>`;}catch(e){$('analyticsBox').innerHTML=`<div class="notice">${esc(e.message)}</div>`;}}
$('mcYear').addEventListener('change',loadControlAssessments);$('mcTerm').addEventListener('change',loadControlAssessments);$('mcAssessment').addEventListener('change',async()=>{const a=await api(`/api/assessments/${sid}/${$('mcYear').value}/${$('mcTerm').value}`);const x=a.find(v=>v.id===$('mcAssessment').value);$('mcDeadline').value=x?.deadline_at?new Date(x.deadline_at).toISOString().slice(0,16):'';});$('saveDeadline').addEventListener('click',async()=>{if(!$('mcYear').value||!$('mcTerm').value||!$('mcAssessment').value)return $('deadlineMsg').textContent='Select academic year, term and assessment first.';try{const r=await api(`/api/assessments/${sid}/${$('mcYear').value}/${$('mcTerm').value}/${$('mcAssessment').value}`,{method:'PATCH',body:{deadline_at:$('mcDeadline').value?new Date($('mcDeadline').value).toISOString():null,status:'OPEN'}});$('deadlineMsg').textContent=r.deadline_at?'Deadline saved: '+new Date(r.deadline_at).toLocaleString():'Deadline cleared.';}catch(e){$('deadlineMsg').textContent=e.message}});$('closeAssessment').addEventListener('click',async()=>{try{await api(`/api/assessments/${sid}/${$('mcYear').value}/${$('mcTerm').value}/${$('mcAssessment').value}`,{method:'PATCH',body:{status:'CLOSED'}});$('deadlineMsg').textContent='Mark entry closed for this assessment.';}catch(e){$('deadlineMsg').textContent=e.message}});$('pubYear').addEventListener('change',async()=>{await terms($('pubYear').value,$('pubTerm'));await loadGradeRoster();});$('pubLevel').addEventListener('change',loadGradeRoster);$('publishGrade').addEventListener('click',async()=>{if(!$('pubYear').value||!$('pubTerm').value||!$('pubLevel').value)return alert('Select academic year, term and grade.');if(!confirm('Publish results for this grade and send the result SMS to linked parents?'))return;try{const r=await api(`/api/communications/${sid}/publish-grade-results`,{method:'POST',body:{academic_year_id:$('pubYear').value,term_id:$('pubTerm').value,level_id:$('pubLevel').value}});$('publishMsg').style.display='block';$('publishMsg').textContent=`Published. Learners: ${r.learners}; SMS processed: ${r.queued}; skipped: ${r.skipped}; failed: ${r.failed}. ${r.message}`;}catch(e){$('publishMsg').style.display='block';$('publishMsg').textContent=e.message}});$('anYear').addEventListener('change',async()=>{await terms($('anYear').value,$('anTerm'));});$('loadAnalytics').addEventListener('click',runAnalytics);

async function loadBilling(){try{const b=await api(`/api/billing/${sid}/summary`);const sub=b.subscription;const inv=b.invoices||[];const outstanding=inv.reduce((a,x)=>a+Math.max(0,Number(x.amount||0)-Number(x.amount_paid||0)),0);$('billPlan').textContent=sub?`${sub.plan_name_snapshot||'Custom'} · ${sub.billing_cycle}`:'Not assigned';$('billDue').textContent=sub?.next_due_on||'—';$('billStatus').textContent=sub?.status||'No subscription';$('billOutstanding').textContent=`${sub?.currency||'KES'} ${outstanding.toFixed(2)}`;const activeNotice=(b.notifications||[])[0];if(activeNotice){$('billingNotice').style.display='block';$('billingNotice').innerHTML=`<b>🔔 ${esc(activeNotice.title)}</b><br>${esc(activeNotice.message)} <button class="btn secondary billing-read" data-id="${activeNotice.id}" type="button">Mark read</button>`;}$('billingInvoices').innerHTML=inv.map(x=>`<div class="item"><b>${esc(x.invoice_no)}</b> · ${esc(x.computed_status||x.status)} · ${esc(x.currency)} ${Number(x.amount).toFixed(2)} · due ${esc(x.due_on)} ${x.amount_paid?`· paid ${Number(x.amount_paid).toFixed(2)}`:''}</div>`).join('')||'No invoices yet.';$('billingMethods').innerHTML=(b.methods||[]).map(x=>`<div class="item"><b>${esc(x.name)}</b><br><span class="muted small">${esc(x.instructions||'Payment instructions will be provided by PRO-MARK.')}</span></div>`).join('')||'No payment methods configured.';const unpaid=inv.filter(x=>!['PAID','WAIVED','CANCELLED'].includes(x.computed_status||x.status));if(isAdmin&&unpaid.length&&b.methods?.length){$('billingPaymentBox').style.display='block';opts($('billingInvoice'),unpaid,x=>`${x.invoice_no} · ${x.currency} ${Number(x.amount-x.amount_paid).toFixed(2)}`);opts($('billingMethod'),b.methods,x=>x.name);$('billingAmount').value=unpaid[0]?Math.max(0,Number(unpaid[0].amount)-Number(unpaid[0].amount_paid)).toFixed(2):'';$('billingInvoice').onchange=()=>{const x=unpaid.find(v=>v.id===$('billingInvoice').value);if(x)$('billingAmount').value=Math.max(0,Number(x.amount)-Number(x.amount_paid)).toFixed(2)}}}catch(e){if(isAdmin||isLeadership)console.warn('Billing unavailable:',e.message)}}
$('billingPaymentForm')?.addEventListener('submit',async e=>{e.preventDefault();try{await api(`/api/billing/${sid}/invoices/${$('billingInvoice').value}/payment-request`,{method:'POST',body:{payment_method_id:$('billingMethod').value,amount:Number($('billingAmount').value),payment_date:$('billingDate').value||null,reference:$('billingReference').value}});$('billingPaymentMessage').textContent='Payment submitted for verification.';await loadBilling();}catch(x){$('billingPaymentMessage').textContent=x.message}});
